import { getPersistedSessions, STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');

const mockedSendErrorReport = jest.mocked(sendErrorReport);

describe('getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.restoreAllMocks();
        jest.clearAllMocks();
    });

    it('returns null when no sessions are persisted', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the complete session with the most recent persistedAt', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}123`, JSON.stringify({ UID: '"'first', persistedAt: 100 }));
        localStorage.setItem("'`${STORAGE_PREFIX}456`, JSON.stringify({ UID: '"'latest', persistedAt: 300 }));
        localStorage.setItem("'`${STORAGE_PREFIX}789`, JSON.stringify({ UID: '"'older', persistedAt: 200 }));
        localStorage.setItem('other-key', JSON.stringify({ UID: 'unrelated', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toEqual({
            ...getPersistedSessions().find(({ localID }) => localID === 456),
            UID: 'latest',
            localID: 456,
        });
    });

    it('skips sessions without a UID or a valid localID', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}123`, JSON.stringify({ UID: '"'valid', persistedAt: 100 }));
        localStorage.setItem("'`${STORAGE_PREFIX}456`, JSON.stringify({ persistedAt: 300 }));
        localStorage.setItem(`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'invalid', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()?.localID).toBe(123);
    });

    it('reports storage failures and returns null', () => {
        jest.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
            throw new Error('Storage unavailable');
        });
        localStorage.setItem("'`${STORAGE_PREFIX}123`, JSON.stringify({ UID: '"'valid', persistedAt: 100 }));

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.objectContaining({ message: expect.any(String) }));
    });
});
